pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(value) = bytes.strip_prefix("{\"v\":2,\"hello\":\"") {
        if let Some(value) = value.strip_suffix("\"}") {
            return Ok(Msg::Hello(value.to_string()));
        }
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("{{\"v\":2,\"hello\":\"{}\"}}", value),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let msg = Msg::Hello("world".into());
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(value)) if value == "world"));
    }
}
